// THE GENERATED HEADER NAMES THE TOOL. A generated file met in someone else's
// game repository has to lead a person, or an AI assistant, back to the
// compiler that wrote it and to the command that writes it again: "the schema
// compiler" is not searchable and names no place. So every header a backend
// writes carries, directly after its "Code generated by the schema compiler
// ... DO NOT EDIT." line, the genheader line: the compiler's URL and how to
// regenerate (internal/codegen/genheader).
//
// The gate is driven from the registry: every target [New] registers is
// generated over the committed corpora, so a backend that lands without the
// line fails here by name, and no list in this file has to be told about it.
package compiler

import (
	"maps"
	"slices"
	"strings"
	"sync"
	"testing"

	"github.com/mas-bandwidth/schema/v2/internal/codegen/genheader"
	"github.com/mas-bandwidth/schema/v2/internal/codegen/gotable"
)

// headerCorpora are the committed units the gate generates: packets, the
// int128/fixed corpus, and table units across the forms the backends emit
// (fixed, block, message, pointers). A target that refuses a corpus's
// constructs is skipped for that corpus; every target must carry the line on
// at least one corpus it accepts.
var headerCorpora = []string{
	"../examples",
	"../examples128",
	"../tables/examples",
	"../tables/block",
	"../tables/messages",
	"../tables/pointers",
}

// testgenCorpus reports whether the generated tests are emitted for a corpus
// here too. The pointer corpus is generated but not testgen'd: its tables
// reach themselves, and `schema testgen --lang lua tables/pointers` does not
// return today (luatable's unreadable-uint64 walk recurses without bound), so
// running it would take this gate down with it.
func testgenCorpus(dir string) bool { return dir != "../tables/pointers" }

const generatedMarker = "Code generated by the schema compiler"

// checkGeneratedHeader reports whether body carries the generated header, and
// fails t when it does and the genheader line does not follow the header's
// first line under the same comment leader.
func checkGeneratedHeader(t *testing.T, where string, body []byte) bool {
	t.Helper()
	text := string(body)
	at := strings.Index(text, generatedMarker)
	if at < 0 {
		return false
	}
	lineStart := strings.LastIndexByte(text[:at], '\n') + 1
	lead := strings.TrimRight(text[lineStart:at], " ")
	if lead == "/*" {
		lead = "  " // the C block comment continues under "/* "
	}
	eol := strings.IndexByte(text[at:], '\n')
	if eol < 0 {
		t.Errorf("%s: the generated header is the whole file, and no genheader line follows it", where)
		return true
	}
	rest := text[at+eol+1:]
	if !strings.HasPrefix(rest, genheader.Line(lead)) && !strings.HasPrefix(rest, genheader.Wrapped(lead)) {
		next, _, _ := strings.Cut(rest, "\n")
		t.Errorf("%s: the line after the generated header is %q, not the genheader line under %q (internal/codegen/genheader)", where, next, lead)
	}
	return true
}

// The corpora are independent, so each is a parallel subtest with its own
// compiler and its own loaded unit (run serially this was 11 s of one
// go-test-touched row on an idle bench, and the row went past ci-fast's
// two-minute cap on a loaded runner); the per-target count is summed after
// every corpus has run.
func TestGeneratedHeaderNamesTheToolInEveryTarget(t *testing.T) {
	t.Parallel()
	targets := New().Targets()
	if len(targets) == 0 {
		t.Fatal("no target is registered; the gate would pass over nothing")
	}
	var mu sync.Mutex
	headed := map[string]int{}
	t.Run("corpora", func(t *testing.T) {
		for _, dir := range headerCorpora {
			t.Run(strings.TrimPrefix(dir, "../"), func(t *testing.T) {
				t.Parallel()
				c := New()
				paths, err := GatherPaths([]string{dir})
				if err != nil {
					t.Fatalf("%s: %v", dir, err)
				}
				u, err := c.Load(paths)
				if err != nil {
					t.Fatalf("%s: %v", dir, err)
				}
				for _, target := range targets {
					n := 0
					check := func(kind string, files map[string][]byte) {
						for _, name := range slices.Sorted(maps.Keys(files)) {
							if checkGeneratedHeader(t, target+" "+kind+" "+u.Package+" "+name, files[name]) {
								n++
							}
						}
					}
					if files, err := c.Generate(u, target, Options{}); err == nil {
						check("generate", files)
					} // else the target refuses a construct this corpus holds
					if testgenCorpus(dir) {
						if files, err := c.Testgen(u, target); err == nil {
							check("testgen", files)
						}
						if target == "luau" {
							if files, err := TestgenLuau(u); err == nil {
								check("testgen", files)
							}
						}
					}
					mu.Lock()
					headed[target] += n
					mu.Unlock()
				}
			})
		}
	})
	for _, target := range targets {
		if headed[target] == 0 {
			t.Errorf("%s: no corpus generated a file with the generated header; the gate checked nothing for this target", target)
		}
	}
	// The optional shared Go runtime package (tables/goruntime) is generated
	// outside any unit and carries the header too.
	rt, err := gotable.SharedRuntimeFiles()
	if err != nil {
		t.Fatal(err)
	}
	for name, body := range rt {
		if !checkGeneratedHeader(t, "go shared runtime "+name, body) && strings.HasSuffix(name, ".go") {
			t.Errorf("go shared runtime %s: no generated header", name)
		}
	}
}

// TestGenheaderLineFitsEveryGate holds the line's own shape: the URL whole on
// one line in both forms, the wrapped form inside the tightest limit that
// wraps it (Java's 100-column canonical form; Lua's luacheck allows 120), and
// no byte a format string would read as a verb.
func TestGenheaderLineFitsEveryGate(t *testing.T) {
	if !strings.Contains(genheader.Text, genheader.URL) || strings.ContainsAny(genheader.Text, "%\n") {
		t.Fatalf("genheader.Text %q must hold the URL whole and no %% or newline", genheader.Text)
	}
	for line := range strings.SplitSeq(strings.TrimSuffix(genheader.Wrapped("//"), "\n"), "\n") {
		if n := len([]rune(line)); n > 100 {
			t.Errorf("wrapped line %q is %d columns, past Java's 100", line, n)
		}
	}
	if first, _, _ := strings.Cut(genheader.Wrapped("--"), "\n"); !strings.Contains(first, genheader.URL) {
		t.Errorf("the wrapped form's first line %q does not carry the URL whole", first)
	}
}
